// ECO-94 §§C2,D,E,J. Bounded source/access comparison method for BUILD 7.
// This interprets explicit fixture evidence; no universal prose evaluator or model-internal claim.
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
export const method = createHash("sha256").update(
  readFileSync(new URL(import.meta.url)),
).digest("hex");
export const obligations = [
  "structural_supply",
  "focal_identity",
  "mapping_access",
  "comparison",
  "coordinates",
  "resolution_question_forward",
  "evidence_pressure",
  "non_promotion",
  "controls",
];
export const capacities = [
  "quadrants",
  "altitude",
  "lines",
  "stages",
  "states",
  "types",
  "directional_frame",
];
const corresponds = (observed, claimed) => observed === claimed;
const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const text = (x) => typeof x === "string" && x.trim().length > 0;
const qf = (q, ct) =>
  q?.question === ct.question_forward.question && q && text(q.question) &&
  q.question.includes("?") && text(q.change) && text(q.notice) &&
  text(q.reentry) && text(q.consequence);
export async function doc(db, id, role = null) {
  const [r] = await db`select ecb7.doc(${id}::uuid,${role}) as value`;
  return r.value;
}
export async function examine(db, candidate, contract) {
  const c = await doc(db, candidate, "b7_candidate");
  const ct = await doc(db, contract, "b7_contract");
  const f = [];
  const add = (obligation, status, reason, witness) =>
    f.push({ obligation, status, reason, witness });
  const check = (o, yes, reason, w) => add(o, yes ? "PASS" : "FAIL", reason, w);
  let g, sources = {};
  try {
    g = await doc(db, c.grammar, "b7_grammar");
    for (const id of [...c.snapshots, ...(g.interpretation_sources ?? [])]) {
      sources[id] = await doc(db, id, "b7_snapshot");
    }
  } catch (e) {
    for (const o of obligations) {
      add(o, "INCOMPLETE", "exact_payload_unavailable", { error: e.message });
    }
    return f;
  }
  const bindingProblems = [];
  for (
    const id of [
      c.grammar,
      c.contract,
      ...c.snapshots,
      ...(g.interpretation_sources ?? []),
    ]
  ) {
    const [r] =
      await db`select encode(payload_digest,'hex') as digest from public.artifacts where id=${id}::uuid`;
    if (!r || c.dependencies?.[id] !== r.digest) bindingProblems.push(id);
  }
  if (c.dependencies?.method !== ct.method) bindingProblems.push("method");
  const absent = capacities.filter((k) =>
    !g.capacities?.[k] || !text(g.capacities[k].meaning) ||
    !text(g.capacities[k].question) || !text(g.capacities[k].source)
  );
  const q = g.capacities?.quadrants?.distinctions;
  const qOK = equal(q, [
    "individual-interior",
    "individual-exterior",
    "collective-interior",
    "collective-exterior",
  ]);
  add(
    "structural_supply",
    absent.length
      ? "INCOMPLETE"
      : qOK && bindingProblems.length === 0
      ? "PASS"
      : "FAIL",
    absent.length
      ? "structural_support_unavailable"
      : qOK
      ? "exact_capacity_closure"
      : "quadrant_collapse",
    { grammar: c.grammar, absent, quadrants: q ?? null, bindingProblems },
  );
  const [scope] =
    await db`select focal::text,contract::text from ecb7.scopes where id=${ct.scope}::uuid`;
  check(
    "focal_identity",
    c.focal === ct.focal && scope?.focal === c.focal &&
      c.contract === contract && scope?.contract === contract &&
      c.focal !== candidate,
    "focal_and_artifact_identity",
    { focal: c.focal, expected: ct.focal, artifact: candidate },
  );
  const mapFindings = [];
  for (const m of c.mappings ?? []) {
    const supplied = g.aliases?.[m.token];
    const source = sources[supplied?.snapshot];
    let claim;
    const [r] =
      await db`select proposition,scope,origin,epistemic_standing from public.claims where id=${m.claim}::uuid`;
    try {
      claim = JSON.parse(r?.proposition);
    } catch {
      claim = null;
    }
    const ok = source && supplied && m.snapshot === supplied.snapshot &&
      m.mapper === source.mapper && m.access === supplied.access &&
      m.focal === c.focal && m.frame?.focal === c.focal &&
      m.frame?.anchor === source.anchor &&
      m.frame?.relation === source.relation && text(source.source) &&
      text(source.version) && text(source.limits) &&
      equal(claim, {
        focal: m.focal,
        anchor: m.frame.anchor,
        relation: m.frame.relation,
        mapper: m.mapper,
        source: m.snapshot,
        access: m.access,
      }) &&
      r?.scope === ct.scope && r?.origin === "ecb_inference";
    mapFindings.push({
      token: m.token,
      source: supplied?.snapshot ?? null,
      access: supplied?.access ?? null,
      ok: Boolean(ok),
      claim: m.claim,
    });
  }
  check(
    "mapping_access",
    mapFindings.length > 0 && mapFindings.every((x) => x.ok),
    "source_mapper_frame_access_separation",
    mapFindings,
  );
  // Comparison expectations are independent of candidate success claims and read from retained sources.
  // The contract's retained interpretation is supplied independently of the producer.
  // This bounded method cannot interpret arbitrary new prose: missing interpretation is INCOMPLETE.
  const expressionMeaning =
    Object.hasOwn(ct.expression_interpretations ?? {}, c.expression)
      ? ct.expression_interpretations[c.expression]
      : null;
  const comparisons = [];
  for (const cmp of ct.comparisons ?? []) {
    const alias = g.aliases?.[cmp.token], src = sources[alias?.snapshot];
    let expected, reason = "source_sensitive_comparison", status = "PASS";
    if (!src || !alias) {
      status = "INCOMPLETE";
      reason = "comparison_source_unavailable";
    } else if (cmp.kind === "observational_discrimination") {
      // Distinct native outputs within the stipulated latency budget, not differences in external readings.
      if (
        !Array.isArray(src.observations) || src.observations.length !== 2 ||
        !Number.isFinite(src.latency)
      ) {
        status = "INCOMPLETE";
        reason = "observation_trace_unavailable";
      } else {expected = src.observations[0] !== src.observations[1] &&
          src.latency <= cmp.decision_interval;}
    } else if (cmp.kind === "reported_preference") {
      expected = alias.access === "testimony" && src.speaker === ct.focal &&
        src.report === cmp.preference;
    } else if (cmp.kind === "collective_agreement") {
      if (!src.convention || !Array.isArray(src.signals)) {
        status = "INDETERMINATE";
        reason = "collective_discriminator_unavailable";
      } else {expected = src.convention === "explicit_all" &&
          src.participants.every((p) => src.signals.includes(p));}
    } else {
      status = "INDETERMINATE";
      reason = "normative_comparator_unavailable";
    }
    const actual = c.conclusions?.find((x) => x.comparison === cmp.id)?.answer;
    if (status === "PASS" && !corresponds(expected, actual)) {
      status = "FAIL";
      reason = "access_or_consequence_substitution";
    }
    const expressionAnswer = expressionMeaning?.[alias?.access];
    if (status !== "FAIL" && typeof expressionAnswer !== "boolean") {
      status = "INCOMPLETE";
      reason = "expression_interpretation_unavailable";
    } else if (status === "PASS" && !corresponds(expected, expressionAnswer)) {
      status = "FAIL";
      reason = "expression_consequence_substitution";
    }
    if (
      !text(cmp.consequence) || !text(cmp.defeater) ||
      !Array.isArray(cmp.alternatives) || cmp.alternatives.length < 2
    ) {
      status = "INDETERMINATE";
      reason = "comparison_contract_incomplete";
    }
    comparisons.push({
      id: cmp.id,
      token: cmp.token,
      source: alias?.snapshot ?? null,
      access: alias?.access ?? null,
      kind: cmp.kind,
      expected: expected ?? null,
      actual: actual ?? null,
      expression: c.expression,
      expression_answer: expressionAnswer ?? null,
      interpretation_contract: contract,
      status,
      reason,
      consequence: cmp.consequence,
    });
  }
  const resultOf = (xs) =>
    xs.some((x) => x.status === "FAIL")
      ? "FAIL"
      : xs.some((x) => x.status === "INCOMPLETE")
      ? "INCOMPLETE"
      : xs.some((x) => x.status === "INDETERMINATE")
      ? "INDETERMINATE"
      : "PASS";
  add(
    "comparison",
    comparisons.length ? resultOf(comparisons) : "INDETERMINATE",
    comparisons.length
      ? "retained_expected_observed_contrast"
      : "normative_comparator_unavailable",
    comparisons,
  );
  const coords = [];
  for (const item of c.coordinates ?? []) {
    const src = sources[item.snapshot];
    const fact = src?.coordinates?.find((x) =>
      x.dimension === item.dimension && x.subject === item.subject &&
      x.line === item.line
    );
    coords.push({
      item,
      expected: fact ?? null,
      ok: Boolean(fact && equal(item.value, fact.value)),
    });
  }
  check(
    "coordinates",
    coords.every((x) => x.ok),
    "level_stage_state_line_type_separation",
    coords,
  );
  const dispositions = [];
  for (const k of capacities) {
    const d = c.dispositions?.[k];
    let ok = true, reason = "inherited_available";
    if (!d) {
      // An omitted overlay remains not_examined; a named omission challenge must cover the comparison.
      ok = text(c.omission_challenges?.[k]);
      reason = "not_examined_with_omission_challenge";
    } else {
      const statuses = [
        "rich",
        "minimal",
        "unresolved",
        "non_live",
        "unsupported",
      ];
      ok = statuses.includes(d.status) && text(d.basis) &&
        text(d.discriminator) && text(d.reexpand);
      if (
        ["minimal", "unresolved", "non_live", "unsupported"].includes(d.status)
      ) ok = ok && qf(d.question_forward, ct);
      if (d.status === "non_live") {
        ok = ok && Array.isArray(d.alternative_consequences) &&
          new Set(d.alternative_consequences).size === 1;
      }
      reason = ok
        ? "resolution_with_reentry"
        : "missing_calibrated_question_or_erasure";
    }
    dispositions.push({
      capacity: k,
      status: d?.status ?? "not_examined",
      ok,
      reason,
    });
  }
  if (!qf(c.question_forward, ct)) {
    dispositions.push({
      capacity: "focal_question",
      ok: false,
      reason: "missing_calibrated_question",
    });
  }
  const materialUnresolved = Object.values(c.dispositions ?? {}).some((d) =>
    d.status === "unresolved" && Array.isArray(d.alternative_consequences) &&
    new Set(d.alternative_consequences).size > 1
  );
  add(
    "resolution_question_forward",
    dispositions.some((x) => !x.ok)
      ? "FAIL"
      : materialUnresolved
      ? "INDETERMINATE"
      : "PASS",
    "resolution_not_erasure",
    dispositions,
  );
  const pressure = [];
  for (const [id, src] of Object.entries(sources)) {
    for (const ev of src.local_evidence ?? []) {
      const retained = c.evidence_dispositions?.find((x) =>
        x.snapshot === id && x.evidence === ev.id
      );
      const ok = retained && text(retained.finding) &&
        (!ev.challenges_rule ||
          (retained.rule === ev.challenges_rule &&
            text(retained.governing_route) &&
            text(retained.affected_decision)));
      pressure.push({
        source: id,
        evidence: ev,
        retained: retained ?? null,
        ok: Boolean(ok),
      });
    }
  }
  const grammarUnchanged = c.governing_revision === g.governing_revision;
  check(
    "evidence_pressure",
    grammarUnchanged && pressure.every((x) => x.ok),
    "local_evidence_retained_without_constitutional_rewrite",
    { grammarUnchanged, pressure },
  );
  const forbidden = [
    "truth",
    "warrant",
    "authority",
    "designation",
    "currentness",
    "execution_authorization",
    "first_person_access",
  ];
  check(
    "non_promotion",
    !(c.promotions ?? []).some((p) => forbidden.includes(p)),
    "qualification_has_no_other_dimension_effect",
    { promotions: c.promotions ?? [], meaning: "comparison_eligibility_only" },
  );
  // Same comparison method: a known wrong answer must disagree, and alternative wording must not matter.
  const decidable = comparisons.filter((x) => typeof x.expected === "boolean");
  if (decidable.length === 0) {
    add(
      "controls",
      resultOf(comparisons) === "INDETERMINATE"
        ? "INDETERMINATE"
        : "INCOMPLETE",
      "control_comparison_unavailable",
      comparisons,
    );
  } else {check(
      "controls",
      decidable.every((x) =>
        corresponds(x.expected, x.expected) &&
        !corresponds(x.expected, !x.expected)
      ) && ct.negative_control === "invert_source_bound_answer",
      "known_defective_answer_rejected_by_same_contrast",
      decidable.map((x) => ({
        id: x.id,
        positive: x.expected,
        defective: !x.expected,
        reason: "access_or_consequence_substitution",
      })),
    );}
  return f;
}
export async function qualify(db, candidate, contract, attempt) {
  await db`select ecb7.attempt(${attempt}::uuid,${candidate}::uuid)`;
  const findings = await examine(db, candidate, contract);
  const [r] = await db`select ecb7.publish(${attempt}::uuid,${
    db.json(findings)
  },${method}) as id`;
  return { id: r.id, ...await doc(db, r.id, "b7_evaluation") };
}

CREATE OR REPLACE FUNCTION ecb8.examine(envelope uuid, contract uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c jsonb; ct jsonb; init jsonb; deps jsonb; d jsonb; f jsonb:='[]'; failures jsonb:='[]'; gaps jsonb:='[]';
 r record; q jsonb; keydoc jsonb; designation jsonb; src jsonb; meaning jsonb; expected_meaning jsonb;
 outcome text; status text; required text[]; actual text[]; id uuid; begin
 c:=ecb8.doc(envelope,'b8_envelope'); ct:=ecb8.doc(contract,'b8_basis');
 init:=ecb8.initial((ct->>'scope')::uuid,(ct->>'action')::uuid);
 if ct->>'kind'<>'contract' then raise exception 'b8_comparison_contract_required'; end if;
 status:='PASS';
 if c->>'contract' is distinct from contract::text or c->>'method' is distinct from ct->>'method'
 or ct->>'method'<>encode(extensions.digest(convert_to(pg_get_functiondef('ecb8.examine(uuid,uuid)'::regprocedure),'UTF8'),'sha256'),'hex')
 or c->>'scope' is distinct from ct->>'scope' or c->>'action' is distinct from ct->>'action'
 or c->>'target' is distinct from init->>'target' or c->>'actor' is distinct from init->>'actor'
 or c->'orientation' is distinct from ct->'orientation' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','exact_binding','status',status,'witness',c-'expression'));
 deps:=c->'dependencies';
 select array_agg(x order by x) into required from (select jsonb_object_keys(ct->'required') x union select contract::text) t;
 select array_agg(x order by x) into actual from jsonb_object_keys(deps) x;
 if required is distinct from actual then gaps:=gaps||jsonb_build_array('required_manifest_members'); end if;
 for r in select * from jsonb_each(ct->'required'||jsonb_build_object(contract::text,jsonb_build_object('role','b8_basis'))) loop
  if not(deps ? r.key) then continue; end if;
  begin
   d:=ecb8.doc(r.key::uuid,r.value->>'role');
   if deps->r.key->>'role' is distinct from r.value->>'role'
    or deps->r.key->>'digest' is distinct from (select encode(payload_digest,'hex') from public.artifacts where public.artifacts.id=r.key::uuid)
    or deps->r.key->>'revision' is distinct from '1' then failures:=failures||jsonb_build_array(r.key); end if;
  exception when others then gaps:=gaps||jsonb_build_array(jsonb_build_object('id',r.key,'gap',sqlerrm)); end;
 end loop;
 status:=case when jsonb_array_length(failures)>0 then 'FAIL' when jsonb_array_length(gaps)>0 then 'INCOMPLETE' else 'PASS' end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','closure','status',status,'witness',jsonb_build_object('mismatches',failures,'gaps',gaps)));
 status:='PASS';
 if c->>'operation' is distinct from 'advance_one' or c->'delta' is distinct from '1'::jsonb
 or c->'max_effects' is distinct from '1'::jsonb or c->'from_value' is distinct from '0'::jsonb
 or c->'target_revision' is distinct from '0'::jsonb or c->'ready' is distinct from 'true'::jsonb
 or c->>'observation_access' is distinct from 'external' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','action_meaning','status',status,'witness',jsonb_build_object('delta',c->'delta','maximum',c->'max_effects','access',c->'observation_access')));
 status:='PASS';
 if c->'temporal' is distinct from '{"issue":[10,12],"admit":[10,20],"effect_before":30,"unrevoked_through_effect":true}'::jsonb
 or c->>'retry' is distinct from 'observe_then_explicit_fence_before_fresh_admission' then status:='FAIL'; end if;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','temporal_retry','status',status,'witness',jsonb_build_object('temporal',c->'temporal','retry',c->'retry')));
 expected_meaning:=jsonb_build_object('target',init->'target','action',ct->'action','from_value',0,'revision',0,'delta',1,'maximum',1,'access','external');
 meaning:=ct->'interpretations'->(c->>'expression');
 status:=case when meaning is null then 'INCOMPLETE' when meaning='null'::jsonb then 'INDETERMINATE'
 when meaning is distinct from expected_meaning then 'FAIL' else 'PASS' end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','expression_meaning','status',status,'witness',jsonb_build_object('expression',c->'expression','interpreted',meaning,'required',expected_meaning)));
 status:='PASS';
 begin
  keydoc:=ecb8.doc((ct->'orientation'->>'key')::uuid,'b7_candidate');
  q:=ecb8.doc((ct->'orientation'->>'evaluation')::uuid,'b7_evaluation');
  designation:=ecb8.doc((ct->'orientation'->>'designation')::uuid,'b7_designation');
  if q->>'outcome'<>'PASS' or q->'basis' is distinct from keydoc or q->>'candidate' is distinct from ct->'orientation'->>'key'
  or designation->>'candidate' is distinct from ct->'orientation'->>'key' or designation->>'evaluation' is distinct from ct->'orientation'->>'evaluation'
  or designation->>'operation'<>'select' or designation->>'scope' is distinct from ct->>'scope'
  or not(keydoc->'conclusions' @> '[{"comparison":"native","answer":false},{"comparison":"external","answer":true}]') then status:='FAIL'; end if;
  -- Explicit source observations and latency/access remain independently retained.
  for r in select * from jsonb_each(ct->'required') where value ? 'access' loop
   src:=ecb8.doc(r.key::uuid,'b7_snapshot');
   if r.value->>'access'='native' and src->'observations' is distinct from '[20,20]'::jsonb then status:='FAIL'; end if;
   if r.value->>'access'='external' and (src->'observations' is distinct from '[20.1,20.2]'::jsonb or (src->>'latency')::numeric>60) then status:='FAIL'; end if;
  end loop;
 exception when others then status:='INCOMPLETE'; end;
 f:=f||jsonb_build_array(jsonb_build_object('obligation','orientation_grounding','status',status,'witness',ct->'orientation'));
 if exists(select 1 from jsonb_array_elements(f) x where x->>'status'='FAIL') then outcome:='FAIL';
 elsif exists(select 1 from jsonb_array_elements(f) x where x->>'status'='INCOMPLETE') then outcome:='INCOMPLETE';
 elsif exists(select 1 from jsonb_array_elements(f) x where x->>'status'='INDETERMINATE') then outcome:='INDETERMINATE'; else outcome:='PASS'; end if;
 return jsonb_build_object('outcome',outcome,'findings',f,'method',ct->'method','envelope',envelope,'contract',contract,
 'scope',ct->'scope','action',ct->'action','meaning','eligibility_only','limits',ct->'limits');
end $function$

